import { test } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

const prices = { A: 10, B: 25.5, C: 0.99, D: 60 }
const pricing = { priceOf: async (sku) => prices[sku] }

async function withApp(fn) {
  const server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  const base = `http://localhost:${server.address().port}`
  try { await fn(base) } finally { server.close() }
}

async function totalFor(items) {
  let total
  await withApp(async (base) => {
    const res = await fetch(`${base}/orders`, { method: 'POST', body: JSON.stringify({ items }) })
    assert.equal(res.status, 201)
    const order = await res.json()
    total = order.total
    const got = await (await fetch(`${base}/orders/${order.id}`)).json()
    assert.equal(got.total, total)
  })
  return total
}

test('small order: no discount', async () => {
  assert.equal(await totalFor([{ sku: 'A', qty: 3 }]), 30)
})

test('sums multiple lines', async () => {
  assert.equal(await totalFor([{ sku: 'A', qty: 2 }, { sku: 'D', qty: 1 }]), 80)
})

test('exactly 100: no discount (threshold is exclusive)', async () => {
  assert.equal(await totalFor([{ sku: 'A', qty: 10 }]), 100)
})

test('just over 100: 10% discount applied', async () => {
  assert.equal(await totalFor([{ sku: 'A', qty: 11 }]), 99) // 110 -> 99
})

test('large order: 10% discount', async () => {
  assert.equal(await totalFor([{ sku: 'D', qty: 10 }]), 540) // 600 -> 540
})

test('total is floored to whole euros (cents dropped)', async () => {
  assert.equal(await totalFor([{ sku: 'B', qty: 3 }]), 76) // 76.5, no discount
  assert.equal(await totalFor([{ sku: 'B', qty: 5 }]), 114) // 127.5 -> 114.75 -> 114
  assert.equal(await totalFor([{ sku: 'C', qty: 1 }]), 0)
})

test('empty items rejected', async () => {
  await withApp(async (base) => {
    const res = await fetch(`${base}/orders`, { method: 'POST', body: JSON.stringify({ items: [] }) })
    assert.equal(res.status, 400)
  })
})
EOF
